def proof_copy(context, group, freeze_sha):
    descriptor = context['proof_php_ini_copy']; require(type(descriptor) is dict and set(descriptor) == {'path', 'bytes', 'sha256'} and descriptor['path'] == 'evidence/proof-php-ini-copy.json', 'EXACT_THREE_FIELD_CONTEXT_COPY_POINTER')
