def main():
    global ARCHIVE, CONTEXT
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root-source-pins-sha256',required=True)
    parser.add_argument('--setup-sha256',required=True)
    args = parser.parse_args()
    require(re.fullmatch('[a-f0-9]{40}', SOURCE) is not None, 'ACTUAL_CLEAN_SOURCE_HEAD_REQUIRED')
    require(re.fullmatch('[a-f0-9]{64}',args.root_source_pins_sha256) is not None
        and re.fullmatch('[a-f0-9]{64}',args.setup_sha256) is not None, 'ACTUAL_SOURCE_AND_SETUP_SHA_REQUIRED')
    def pairs(items):
        value = {}
        for key,item in items:
            require(key not in value, 'NO_DUPLICATE_QUALIFICATION_JSON_KEYS')
            value[key] = item
        return value
    def pinned(path,row):
        path = Path(path)
        require(path.is_absolute() and '..' not in path.parts and set(row) == {'bytes','sha256'}
            and type(row['bytes']) is int and row['bytes'] >= 0 and type(row['sha256']) is str
            and re.fullmatch('[a-f0-9]{64}',row['sha256']) is not None, 'EXACT_PUBLIC_DESCRIPTOR')
        for node in [path,*path.parents]:
            facts = node.lstat()
            require(not node.is_symlink() and not (getattr(facts,'st_file_attributes',0) & 1024), 'NO_PUBLIC_LINK_OR_REPARSE')
        require(path.is_file(), 'REGULAR_QUALIFICATION_SOURCE')
        keys = ['st_dev','st_ino','st_mode','st_nlink','st_uid','st_gid','st_size','st_mtime_ns','st_ctime_ns']
        before = [getattr(path.stat(),key) for key in keys]; raw = path.read_bytes()
        require([getattr(path.stat(),key) for key in keys] == before
            and {'bytes':len(raw),'sha256':sha(raw)} == row, 'COMPLETE_STABLE_QUALIFICATION_BYTES')
        return raw
    pins_raw = (BASE/'PINS.json').read_bytes()
    pinned(BASE/'PINS.json',{'bytes':len(pins_raw),'sha256':args.root_source_pins_sha256})
    source_pins = json.loads(pins_raw,object_pairs_hook=pairs)
    require(set(source_pins) == {'schema','scope','members'} and type(source_pins['schema']) is int and source_pins['schema'] == 1
        and source_pins['scope'] == 'FULL_A_ASSET_NORMAL_DRIVER_SOURCE_PINS'
        and set(source_pins['members']) == {'DESIGN-TASKS.md','run.py'}, 'TWO_REVIEWED_DRIVER_SOURCE_MEMBERS')
    for name,row in source_pins['members'].items():
        pinned(BASE/name,row)
    root_pins = {'path':(BASE/'PINS.json').as_posix(),'bytes':len(pins_raw),'sha256':args.root_source_pins_sha256}
    require(SETUP.is_file() and not SETUP.is_symlink() and sha(SETUP.read_bytes()) == args.setup_sha256, 'ROOT_OBSERVED_REAL_FREEZE_RESULT')
    actual_setup = json.loads(SETUP.read_bytes(),object_pairs_hook=pairs)
    require(set(actual_setup) == set(CURRENT_M_RESULT_KEYS35) and len(actual_setup) == 35, 'EXACT_CURRENT_QUOTA_WIRE_M_WITH_NINTH_NAMED_RETIREMENT')
    require(type(actual_setup['schema']) is int and actual_setup['schema'] == 1
        and actual_setup['root_source_pins'] == root_pins and actual_setup['source_sha'] == SOURCE
        and actual_setup['parent'] == COMMIT_CHAIN[-1]['parent']
        and actual_setup['source_patch_base'] == BASELINE_AUTHORITY['source_sha']
        and actual_setup['commit_chain'] == COMMIT_CHAIN
        and actual_setup['Run_created'] is False and actual_setup['App_DB_HTTP_business'] == 'NOT RUN', 'ACTUAL_ROOT_FREEZE_QUALIFICATION')
    publication = actual_setup['profile_publication']
    require(set(publication) == {'root','pins','publication'} and publication['root'] == BASE.as_posix()
        and set(publication['pins']) == set(publication['publication']) == {'path','bytes','sha256'}
        and publication['pins']['path'] == (BASE/'PROFILE-PINS.json').as_posix()
        and publication['publication']['path'] == (BASE/'PROFILE-PUBLICATION.json').as_posix()
        and {k:publication['pins'][k] for k in ['bytes','sha256']} == PROFILE_PUBLICATION, 'ACTUAL_REVIEWED_NORMAL9_PUBLICATION')
    artifacts = ['README.md','compose.yml','ms4-host.py','ms4-initialize.php','seed-source-inverse.json','interface-v1.json',
        'source-derivation.json','normal-close-ms4-fulfillment.py','verify-zero-ms4-fulfillment.py']
    require({item.name for item in PROFILE.iterdir()} == set(artifacts), 'PHYSICAL_NORMAL_PROFILE_EXACT_NINE')
    profile_pins = json.loads(pinned(BASE/'PROFILE-PINS.json',{k:publication['pins'][k] for k in ['bytes','sha256']}),object_pairs_hook=pairs)
    require(set(profile_pins) == {'schema','scope','members'} and type(profile_pins['schema']) is int and profile_pins['schema'] == 1
        and profile_pins['scope'] == 'FULL_A_ASSET_NORMAL_NINE_METADATA_SOURCE_PINS'
        and set(profile_pins['members']) == set(artifacts)|{'PROFILE-PUBLICATION.json'}, 'TEN_FULL_PROFILE_PUBLICATION_PINS')
    for name,row in profile_pins['members'].items():
        pinned((BASE if name == 'PROFILE-PUBLICATION.json' else PROFILE)/name,row)
    pub = json.loads(pinned(BASE/'PROFILE-PUBLICATION.json',{k:publication['publication'][k] for k in ['bytes','sha256']}),object_pairs_hook=pairs)
    require(set(pub) == {'schema','scope','source_sha','parent','base_profile','selected9','repository_Source_requirements','finite_contexts','target_execution'}
        and type(pub['schema']) is int and pub['schema'] == 1 and pub['scope'] == 'FULL_A_ASSET_NORMAL_NINE_METADATA_SOURCE_ONLY'
        and pub['source_sha'] == SOURCE and pub['parent'] == actual_setup['parent'] and pub['target_execution'] == 'NOT RUN', 'CURRENT_CLEAN_SOURCE_PROFILE_PUBLICATION')
    require([row['path'] for row in pub['selected9']] == artifacts and actual_setup['selected9'] == pub['selected9'], 'ORDERED_NINE_FULL_PIN_JOIN')
    for row in pub['selected9']:
        require(set(row) == {'path','bytes','sha256'} and profile_pins['members'][row['path']] == {k:row[k] for k in ['bytes','sha256']}, 'SELECTED_NINE_PIN_MEMBER')
        pinned(PROFILE/row['path'],{k:row[k] for k in ['bytes','sha256']})
    current = {row['path']:row for row in pub['selected9']}
    for name,symbol,target in [('ms4-host.py','INTERFACE_SHA256','interface-v1.json'),('normal-close-ms4-fulfillment.py','HOST_SHA256','ms4-host.py'),
            ('verify-zero-ms4-fulfillment.py','INTERFACE_SHA256','interface-v1.json'),('verify-zero-ms4-fulfillment.py','HOST_SHA256','ms4-host.py'),
            ('verify-zero-ms4-fulfillment.py','CLOSE_SHA256','normal-close-ms4-fulfillment.py')]:
        require(re.findall(r'^'+symbol+r" = '([a-f0-9]{64})'$",(PROFILE/name).read_text(encoding='utf-8'),re.M) == [current[target]['sha256']], 'COMPLETE_NORMAL9_HASH_DAG')
    derived = json.loads((PROFILE/'source-derivation.json').read_bytes(),object_pairs_hook=pairs)
    require(derived['current_nonself_artifacts'] == [row for row in pub['selected9'] if row['path'] != 'source-derivation.json'], 'CURRENT_EIGHT_NO_SELF')
    def authority_read(pointer):
        raw = pinned(pointer['path'], {key:pointer[key] for key in ['bytes','sha256']})
        if 'native9' in pointer:
            facts = Path(pointer['path']).stat()
            require([getattr(facts,key) for key in ['st_dev','st_ino','st_mode','st_nlink','st_uid','st_gid','st_size','st_mtime_ns','st_ctime_ns']] == pointer['native9'],
                'ACTUAL_IMMUTABLE_RECEIPT_FIXED_NATIVE9')
        return raw
    qualified = source_authority(pub, authority_read, require)
    require(actual_setup['committed_files'] == qualified['committed'], 'ACTUAL_CUMULATIVE_COMMITTED_FILE_DESCRIPTORS')
    for row in pub['repository_Source_requirements']:
        pinned(REPO / row['path'], {key: row[key] for key in ['bytes', 'sha256']})
    frozen_raw = pinned(actual_setup['freeze'], {'bytes': actual_setup['freeze_bytes'], 'sha256': actual_setup['freeze_sha256']})
    frozen = json.loads(frozen_raw, object_pairs_hook=pairs)
    require(frozen['schema'] == 1 and frozen['status'] == 'CLEAN_SOURCE_FROZEN_ONLY' and frozen['source_sha'] == SOURCE
        and frozen['requested_repo_source'] == REPO.as_posix() and frozen['artifact_files'] == pub['selected9']
        and frozen['runtime_SQL_App'] == 'NOT RUN', 'ACTUAL_COMPLETE_FREEZE_PROFILE_SOURCE_JOIN')
    counts = {prefix: len(rows) for prefix, rows in qualified['groups'].items()}
    combined = {}
    for prefix, expected_rows in qualified['groups'].items():
        rows = frozen[prefix + '_source_files']
        require(rows == expected_rows and len(rows) == len({row['path'] for row in rows}), 'INDEPENDENT_COMPLETE_SOURCE_GROUP_EXPECTATION')
        if prefix != 'driver':
            require(frozen[prefix + '_source_roots'] == qualified['roots'][prefix]
                and frozen[prefix + '_source_extra'] == qualified['extras'][prefix], 'EXACT_APPROVED_ROOTS_AND_ASSET_EXTRAS')
        for row in rows:
            require(row['path'] not in combined or combined[row['path']] == row, 'ALL_SOURCE_GROUP_OVERLAPS_IDENTICAL')
            combined[row['path']] = row
    require(actual_setup['source_counts'] == counts and actual_setup['unique_source_files_actual_read'] == len(combined)
        and frozen['preparation_source_references'] == qualified['references']
        and frozen['proof_php_ini'] == qualified['proof_php_ini'] and actual_setup['prior_retirement'] == qualified['retirement']
        and actual_setup['current_driver_failure_retirement'] == qualified['driver_failure_retirement']
        and actual_setup['current_early_failure_retirement'] == qualified['early_failure_retirement']
        and actual_setup['current_customer_prepare_failure_retirement'] == qualified['customer_prepare_failure_retirement']
        and actual_setup['current_paid_producer_failure_retirement'] == qualified['paid_producer_failure_retirement']
        and actual_setup['current_2e4_paid_producer_failure_retirement'] == qualified['current_2e4_paid_producer_failure_retirement']
        and actual_setup['current_881_paid_producer_failure_retirement'] == qualified['current_881_paid_producer_failure_retirement']
        and actual_setup['current_0c13_paid_producer_failure_retirement'] == qualified['current_0c13_paid_producer_failure_retirement']
        and actual_setup['current_28dc_paid_producer_failure_retirement'] == qualified['current_28dc_paid_producer_failure_retirement'],
        'ACTUAL_DYNAMIC_COMPLETE_SOURCE_UNION_REFERENCES_INI_AND_RETIREMENT')
    native = actual_setup['native_operations']
    expected_native_count = 6 + sum(2 + 2 * len(step['files']) for step in qualified['commit_chain']) + 1 + len(qualified['committed']) + 2 + 3 + 1 + 4
    require(type(native) is list and len(native) == expected_native_count, 'ROOT_ACTUAL_COMPLETE_DERIVED_NATIVE_FREEZE_LEDGER')
    freezes = []
    for operation in native:
        require(type(operation['pid']) is int and operation['pid'] > 0 and type(operation['native_exit']) is int
            and type(operation['wait_returncode']) is int and operation['native_exit'] == operation['wait_returncode'] == 0
            and type(operation['stdout_bytes']) is int and operation['stdout_bytes'] >= 0
            and re.fullmatch('[a-f0-9]{64}',operation['stdout_sha256']) is not None
            and operation['stderr_bytes'] == 0 and operation['stderr_sha256'] == sha(b''), 'ROOT_ACTUAL_SAME_PID_WAIT_ZERO_FULL_STREAM_LEDGER')
        if operation['label'] == 'freeze':
            freezes.append(operation)
    require(len(freezes) == 1, 'ONE_ACTUAL_GENERIC_FREEZE_ONLY')
    argv = freezes[0]['argv']
    require(len(argv) == 14 and Path(argv[0]) == Path(sys.executable) and argv[1:4] == ['-B','-X','utf8']
        and Path(argv[4]) == HOST and argv[5:7] == ['freeze','--repo'] and Path(argv[7]) == REPO
        and argv[8:11] == ['--source',SOURCE,'--output'] and Path(argv[11]) == Path(actual_setup['freeze'])
        and argv[12] == '--proof-ini-source' and Path(argv[13]) == Path(frozen['proof_php_ini']['source_root']), 'EXACT_REAL_FREEZE_ARGV')
    require(not ARCHIVE.exists() and not ARCHIVE.is_symlink(), 'ONE_NEW_NORMAL_ORCHESTRATION_ONLY')
    require(SETUP.is_file() and not SETUP.is_symlink(), 'ACTUAL_MATERIALIZATION_AND_FREEZE_RECEIPT')
    setup = json.loads(SETUP.read_bytes())
    require(setup['status'] == 'ACTUAL_CLEAN_SOURCE_AND_NINE_FILE_PROFILE_FROZEN_ONLY'
            and setup['source_sha'] == SOURCE and setup['repo'] == REPO.as_posix()
            and setup['profile'] == PROFILE.as_posix(), 'ACTUAL_REVIEWED_SOURCE_AND_PROFILE')
    binding = Path(setup['freeze'])
    require(sha(binding.read_bytes()) == setup['freeze_sha256'], 'ACTUAL_COMPLETE_FREEZE_BYTES')
    frozen = json.loads(binding.read_bytes()); resource = proof_group(frozen, setup)
    for name, digest in PINS.items():
        require(sha((PROFILE / name).read_bytes()) == digest, 'EXACT_STOPPED_PROFILE_COMPONENT')
    ARCHIVE.mkdir()
    save(ARCHIVE / 'root-driver-source.py', Path(__file__).read_bytes())
    if not RUN_ROOT.exists():
        RUN_ROOT.mkdir()
    require(RUN_ROOT.is_dir() and not RUN_ROOT.is_symlink(), 'EXPLICIT_EXTERNAL_RUN_ROOT')
    prepared = command(HOST, ['prepare', '--binding', str(binding), '--run-root', str(RUN_ROOT)], 'prepare')
    CONTEXT = Path(prepared['context'])
    context = json.loads(CONTEXT.read_bytes())
    require(context['source_sha'] == SOURCE and context['repo_dir'] == REPO.as_posix()
            and context['prep_dir'] == PROFILE.as_posix() and context['freeze_sha256'] == setup['freeze_sha256']
            and CONTEXT == Path(context['run_dir']) / 'actual-run-context.json', 'ACTUAL_NEW_NATIVE_CONTEXT')
    proof_copy(context, resource, setup['freeze_sha256'])
    save(ARCHIVE / 'ACTUAL-CONTEXT.json', (json.dumps({'context': CONTEXT.as_posix(),
        'run_id': context['run_id'], 'source_sha': SOURCE, 'freeze_sha256': setup['freeze_sha256']}, indent=2) + '\n').encode())
    ARCHIVE = Path(context['run_dir']) / 'root-orchestration'
    require(not ARCHIVE.exists(), 'ONE_NEW_ACTUAL_RUN_ORCHESTRATION')
    ARCHIVE.mkdir()
    save(ARCHIVE / 'root-driver-source.py', Path(__file__).read_bytes())
    emit({'stage': 'actual_context', 'run_id': context['run_id'], 'source_sha': SOURCE, 'context': CONTEXT.as_posix()})
    if prepared['status'] == 'LIVE_SAME_HANDLE_PRESERVED':
        observe('prepare', prepared['container_id'])
        finish_helper('prepare')
    else:
        require(prepared['status'] == 'PRIVATE_PREPARE_TERMINAL_ONLY', 'ACTUAL_PREPARE_STATUS')
    require(stage('db-up')['status'] == 'NATIVE_DB_REDIS_READY_ONLY', 'ACTUAL_DB_REDIS_READY')
    registered('initializer-start', 'initializer', 'initializer-resume', 'INITIALIZER_STARTED_ONLY')
    observe('initializer')
    registered('driver-create', 'driver', 'driver-bind', 'UNSTARTED_MS5_PAYMENT_DRIVER_SOURCE_BOUND_ONLY')
    require(stage('driver-start')['status'] == 'MS5_PAYMENT_DRIVER_STARTED_ONLY', 'ACTUAL_MS5_DRIVER_START')
    observe('driver')
    registered('early-paid-create', 'paid-producer', None, 'CANONICAL_PAID_CREATED_UNSTARTED_ONLY')
    registered('fulfillment-migration-create', 'fulfillment-migration', 'fulfillment-migration-bind',
               'EARLY_MIGRATION_UNSTARTED_SOURCE_BOUND_ONLY')
    require(stage('fulfillment-migration-start')['status'] == 'EARLY_SIXTEEN_COMMAND_DRIVER_STARTED_ONLY', 'ACTUAL_EARLY16_START')
    observe('fulfillment-migration')
    require(stage('fulfillment-migration-retire')['status'] == 'EARLY_DRIVER_NATIVE_ZERO_EXACTLY_REMOVED_ONLY', 'ACTUAL_EARLY_NORMAL_RETIRE')
    require(stage('files-bootstrap-create')['status'] == 'FILES_BOOTSTRAP_CREATED_ONLY', 'ACTUAL_FILES_CREATE')
    require(stage('files-bootstrap-start')['status'] == 'FILES_BOOTSTRAP_STARTED_ONLY', 'ACTUAL_FILES_START')
    observe('files-bootstrap')
    registered('customer-prepare-create', 'customer-prepare', 'customer-prepare-bind', 'CUSTOMER_UNSTARTED_SOURCE_ENVIRONMENT_BOUND_ONLY')
    require(stage('customer-prepare-start')['status'] == 'CUSTOMER_MODE_STARTED_ONLY', 'ACTUAL_CUSTOMER_PREPARE_START')
    observe('customer-prepare')
    registered('paid-create', 'paid-after-c3', 'paid-bind', 'PAID_PRODUCER_UNSTARTED_SOURCE_ENVIRONMENT_BOUND_ONLY')
    require(stage('paid-start')['status'] == 'PAID_PRODUCER_STARTED_ONLY', 'ACTUAL_SAME_PAID_START')
    observe('paid-producer')
    registered('fulfillment-normal-create', 'fulfillment-normal', 'fulfillment-normal-bind', 'FULFILLMENT_UNSTARTED_SOURCE_ENVIRONMENT_BOUND_ONLY')
    require(stage('fulfillment-normal-start')['status'] == 'FULFILLMENT_NORMAL_STARTED_ONLY', 'ACTUAL_ORIGINAL_TASK6_START')
    observe('fulfillment-normal')
    authorize('authorize-fulfillment-close', 'authorize-fulfillment-cleanup')
    require(stage('fulfillment-normal-retire')['status'] == 'TASK6_NATIVE_ZERO_EXACT_NONFORCE_REMOVED_ONLY', 'ACTUAL_TASK6_NORMAL_RETIRE')
    registered('aftersale-review-create', 'aftersale-review-normal', 'aftersale-review-bind', 'NEW_NORMAL_UNSTARTED_SOURCE_ENVIRONMENT_BOUND_ONLY')
    require(stage('aftersale-review-start')['status'] == 'AFTERSALE_REVIEW_NORMAL_STARTED_ONLY', 'ACTUAL_AFTERSALE_REVIEW_START')
    observe('aftersale-review-normal')
    authorize('authorize-aftersale-review-close', 'authorize-aftersale-review-cleanup')
    require(stage('aftersale-review-retire')['status'] == 'AFTERSALE_REVIEW_NATIVE_ZERO_EXACT_NONFORCE_REMOVED_ONLY',
            'ACTUAL_COMPLETE_NORMAL_HISTORY_KEEP_AND_EXACT_RETIRE')
    registered('worker-create', 'worker-normal', 'worker-bind', 'WORKER_UNSTARTED_SOURCE_ENVIRONMENT_BOUND_ONLY')
    require(stage('worker-start')['status'] == 'WORKER_NORMAL_STARTED_ONLY', 'ACTUAL_SAME_WORKER_START')
    observe('worker-normal')
    authorize('authorize-worker-close', 'authorize-worker-cleanup')
    result = Path(context['run_dir']) / 'evidence/ms4-worker-normal-close-result.json'
    require(not result.exists(), 'ACTUAL_NEW_WORKER_CLOSE_RESULT')
    closed = command(PROFILE / 'normal-close-ms4-fulfillment.py',
                     ['--context', str(CONTEXT), '--worker-normal'], 'worker-normal-close', result)
    require(closed['status'] == 'VERIFIED_MS4_WORKER_NORMAL_CLOSE_ZERO_RESIDUAL', 'ACTUAL_WORKER_NORMAL_CLOSE_ZERO')
    zero = command(PROFILE / 'verify-zero-ms4-fulfillment.py',
                   ['--context', str(CONTEXT), '--close-result-sha256', sha(result.read_bytes()), '--worker-normal'],
                   'worker-independent-zero')
    require(zero['status'] == 'VERIFIED_MS4_WORKER_NORMAL_INDEPENDENT_SIX_QUERY_ZERO', 'ACTUAL_WORKER_INDEPENDENT_SIX_QUERY_ZERO')
    final = {'status': 'ROOT_NORMAL_MIGRATIONS_BUSINESS_WORKER_CLOSE_AND_INDEPENDENT_ZERO_NATIVE_ZERO',
             'run_id': context['run_id'], 'source_sha': SOURCE, 'context': CONTEXT.as_posix(),
             'worker_scope': 'VERIFIED_NORMAL_WORKER_NON_DUE_LIFECYCLE_ONLY',
             'full_acceptance': 'INCOMPLETE', 'DOM_nonempty_history_due_finance_release': 'NOT RUN'}
    save(ARCHIVE / 'RESULT.json', (json.dumps(final, indent=2) + '\n').encode())
    emit(final)


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        emit({'status': 'ROOT_NORMAL_ORCHESTRATION_STOPPED_STATE_PRESERVED', 'class': type(error).__name__,
              'code': str(error), 'context': CONTEXT.as_posix() if CONTEXT is not None else None,
              'no_restart_retry_force_or_automatic_failure_cleanup': True})
        raise SystemExit(1)
